-- partition-overwrite pattern (pseudocode)
-- 1. compute into staging:  CREATE TABLE stg AS SELECT ... WHERE dt='2026-10-09'
-- 2. validate:               SELECT COUNT(*), SUM(revenue) FROM stg  -- sanity
-- 3. atomic swap:            DELETE FROM mart WHERE dt='2026-10-09';
--                            INSERT INTO mart SELECT * FROM stg;
-- rerun-safe: step 3 repeated = identical result

# contract.yaml (the depended-upon fields only)
fields:
  - { name: order_id, type: string, nullable: false }
  - { name: amount_cents, type: int, nullable: false, semantics: 'USD cents, >= 0' }
  - { name: email, type: string, nullable: true }
policy: { notice: 14d, or: versioned_parallel_field }
enforcement: { producer_ci: validate, consumer: quarantine_on_violation }

-- native: 25 min on 1TB
SELECT to_timestamp(ts_str, 'yyyy-MM-dd HH:mm:ss') FROM events;
-- row Python UDF: 4 hours on the same 1TB (serialization + no codegen)
-- vectorized alternative when native can't express it:
@pandas_udf('timestamp')
def parse_ts(s: pd.Series) -> pd.Series:
    return pd.to_datetime(s, format='%Y-%m-%d %H:%M:%S')
